        var exception = new Exception("Test exception");

        // Act
        byte[] record = new byte[10];
        fixed (byte* recordPtr = record)
        {
            Action act = () => replicationReplicaAofSync.ProcessPrimaryStream(recordPtr, 0, 0, 0, 0);
